/* @lc app=leetcode id=3303 lang=kotlin */ class Solution { fun z(t: String): IntArray = IntArray(t.length).also { z -> (1 until t.length).fold(0 to 0) { (l, r), i -> (if (i < r) minOf(r - i, z[i - l]) else 0).let { k0 -> (k0 + generateSequence(k0) { it + 1 }.takeWhile { i + it < t.length && t[it] == t[i + it] }.count()).let { k -> z.set(i, k).let { if (i + k > r) i to i + k else l to r } } } } } fun minStartingIndex(s: String, pattern: String): Int = pattern.length.let { m -> z(pattern + "#" + s).let { a -> z(pattern.reversed() + "#" + s.reversed()).let { b -> (0..s.length - m).firstOrNull { i -> a[m + 1 + i] + b[m + 1 + (s.length - 1 - (i + m - 1))] >= m - 1 } ?: -1 } } } }